export type Item = {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
};

export type Damage = { itemType: string; amount: number };

export type QuoteStep = { op: "quote"; items: Item[] };
export type ClaimStep = {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
};
export type Step = QuoteStep | ClaimStep;

export type Scenario = { customer: { yearsWithMHPCO: number }; steps: Step[] };

export type QuoteResult = { premium: number };
export type ClaimResult = { payout: number; remainingCap: number };
export type Result = QuoteResult | ClaimResult;

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
};

const basePremiumOf = (item: Item): number =>
  BASE_PREMIUM_BY_ITEM_TYPE[item.type];

export const runScenario = (scenario: Scenario): { results: Result[] } => {
  const step = scenario.steps[0] as QuoteStep;
  const basePremium = step.items.reduce(
    (sum, item) => sum + basePremiumOf(item),
    0,
  );
  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
  const premium = basePremium + firstInsuranceSurcharge + PROCESSING_FEE;
  return { results: [{ premium }] };
};
